func ingredientDisplay(ing dto.IngredientResult) string {
	if ing.Raw != "" {
		return ing.Raw
	}
	s := ""
	if ing.Amount != "" {
		s += ing.Amount + " "
	}
	if ing.Unit != "" {
		s += ing.Unit + " "
	}
	s += ing.Name
	if ing.Notes != "" {
		s += ", " + ing.Notes
	}
	return s
}

